// يحوّل جسم الـ Webhook إلى شكل موحّد ويحدد نوع الملف المرفوع (إن وُجد)
const w = $('Webhook').first();
const u = $('Verify User').first().json;
const bin = w.binary || {};
const keys = Object.keys(bin);
let file_kind = 'none';
let binary;
if (keys.length > 0) {
  const b = bin[keys[0]];
  const name = String(b.fileName || '').toLowerCase();
  const mime = String(b.mimeType || '').toLowerCase();
  if (mime.includes('pdf') || name.endsWith('.pdf') || mime.startsWith('image/') || /\.(jpe?g|png)$/.test(name)) file_kind = 'media';
  else if (mime.includes('wordprocessingml') || name.endsWith('.docx')) file_kind = 'docx';
  else file_kind = 'other';
  binary = { data: b };
}
const item = { json: { ...(w.json.body || {}), user_id: u.id, user_email: u.email, file_kind } };
if (binary) item.binary = binary;
return [item];

const it = $input.first();
const b = it.binary.data;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
let mime = String(b.mimeType || '').toLowerCase();
const name = String(b.fileName || '').toLowerCase();
if (!mime || mime === 'application/octet-stream') {
  if (name.endsWith('.pdf')) mime = 'application/pdf';
  else if (/\.jpe?g$/.test(name)) mime = 'image/jpeg';
  else if (name.endsWith('.png')) mime = 'image/png';
}
return [{ json: { ...it.json, file_b64: buf.toString('base64'), file_mime: mime, ocr_prompt: 'اقرأ كل النص الظاهر في الملف بدقة، بما في ذلك النص الموجود داخل الصور، مع الحفاظ على ترتيب الفقرات وترقيم البنود والأرقام والتواريخ والمبالغ، وأعد النص فقط دون تلخيص.' } }];

const base = $('Upload Contract').first().json;
// n8n قد يعيد استجابة HTTP مباشرة أو داخل body، لذلك نقرأ الشكلين.
const response = ($json && $json.body && typeof $json.body === 'object') ? $json.body : ($json || {});
const candidates = Array.isArray(response.candidates) ? response.candidates : [];
let text = candidates
  .flatMap(c => (c.content && Array.isArray(c.content.parts)) ? c.content.parts : [])
  .filter(p => typeof p.text === 'string' && !p.thought)
  .map(p => p.text)
  .join('')
  .trim();
// دعم استجابات Gemini المبسطة أو أي wrapper محتمل من عقدة HTTP.
if (!text && typeof response.text === 'string') text = response.text.trim();
if (!text && typeof response.output === 'string') text = response.output.trim();
if (!text && typeof response.result === 'string') text = response.result.trim();
if (!text && response.content && Array.isArray(response.content.parts)) {
  text = response.content.parts.filter(p => typeof p.text === 'string').map(p => p.text).join('').trim();
}
const finish = candidates[0]?.finishReason || '';
let error = '';
if (!text) {
  error = finish ? 'تعذر استخراج النص من الملف عبر OCR. سبب Gemini: ' + finish : 'تعذر استخراج نص من الملف المرفوع عبر OCR. تأكد أن صفحات الملف واضحة وأن عقدة Gemini متصلة باعتماد صحيح.';
}
return [{ json: { ...base, extracted_text: text, file_error: error, ocr_used: true } }];

const j = $json;
const pick = (a, b) => (j[a] !== undefined ? j[a] : j[b]) || '';
const contractType = String(pick('contract_type', 'نوع العقد')).trim();
const userRole = String(pick('user_role', 'صفة المستخدم')).trim();
let typed = String(pick('contract_text', 'نص العقد'));

let fileText = '';
let fileNote = '';
const binary = $input.item.binary || {};
for (const key of Object.keys(binary)) {
  const meta = binary[key];
  const mime = (meta.mimeType || '').toLowerCase();
  const fname = meta.fileName || key;
  if (mime.startsWith('text/') || fname.toLowerCase().endsWith('.txt')) {
    try {
      const buf = await this.helpers.getBinaryDataBuffer($itemIndex, key);
      fileText += '\n' + buf.toString('utf8');
    } catch (e) {
      fileNote += 'تعذر قراءة الملف ' + fname + '. ';
    }
  } else if (mime.includes('pdf')) {
    try {
      const raw = (await this.helpers.getBinaryDataBuffer($itemIndex, key)).toString('latin1');
      const parts = [];
      const re = /\(((?:\\.|[^\\)])*)\)\s*Tj/g;
      let m;
      while ((m = re.exec(raw)) !== null) parts.push(m[1]);
      if (parts.length > 20) fileText += '\n' + parts.join(' ');
      else fileNote += 'تم استلام ملف PDF (' + fname + ') والاعتماد على النص المُدخل. ';
    } catch (e) {
      fileNote += 'تعذر قراءة الملف ' + fname + '. ';
    }
  } else {
    fileNote += 'تم استلام الملف ' + fname + ' والاعتماد على النص المُدخل. ';
  }
}

const extra = String(j.extracted_text || '');
if (extra) fileText += '\n' + extra;
if (j.file_error) fileNote += j.file_error + ' ';

const clean = (s) => s
  .replace(/\r\n/g, '\n')
  .replace(/[\u200B-\u200F\u202A-\u202E\uFEFF]/g, '')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

typed = clean(typed);
fileText = clean(fileText);
let contractText = typed;
if (fileText && !typed.includes(fileText.slice(0, 200))) {
  contractText = typed ? typed + '\n\n--- نص مستخرج من الملف المرفق ---\n' + fileText : fileText;
}

return { json: { contract_type: contractType, user_role: userRole, contract_text: contractText, file_note: fileNote.trim(), char_count: contractText.length, has_text: contractText.length >= 30 } };

