</div></body></html>`;
return [{ json: { status: 'done', report: html, error: null } }];

const base = $('Upload Contract').first().json;
const bin = $input.first().binary || {};
const keys = Object.keys(bin);
let key = keys.find(k => bin[k].fileName === 'document.xml' && String(bin[k].directory || '').includes('word'));
if (!key) key = keys.find(k => bin[k].fileName === 'document.xml');
if (!key) return [{ json: { ...base, extracted_text: '', file_error: 'تعذّر قراءة ملف Word.' } }];
const buffer = await this.helpers.getBinaryDataBuffer(0, key);
const text = buffer.toString('utf8')
  .replace(/<w:tab\/>/g, '\t')
  .replace(/<w:br[^>]*\/>/g, '\n')
  .replace(/<\/w:p>/g, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
return [{ json: { ...base, extracted_text: text, file_error: text ? '' : 'ملف Word لا يحتوي على نص.' } }];
